#include "core.hpp"
#include <cstring>
#include <stdexcept>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("input.qdelta output.raw");std::ifstream in(argv[1],std::ios::binary);std::ofstream out(argv[2],std::ios::binary);char magic[8];int hdr[4];in.read(magic,8);in.read((char*)hdr,16);if(!in||memcmp(magic,"AST5CP1",7)||hdr[0]!=24||hdr[1]!=N||hdr[2]!=80730||hdr[3]!=32)throw std::runtime_error("header mismatch");out.write(magic,8);out.write((char*)hdr,16);const int H=80730;std::vector<unsigned char>lo(H),hi(H);std::vector<int16_t>q(H);for(int b=0;b<2;b++)for(int p=0;p<=N;p++){float base;in.read((char*)&base,4);in.read((char*)lo.data(),H);in.read((char*)hi.data(),H);if(!in)throw std::runtime_error("truncated checkpoint");uint16_t prev=0;for(int h=0;h<H;h++){prev=uint16_t(prev+uint16_t(lo[h]|(uint16_t(hi[h])<<8)));q[h]=int16_t(prev);}if(q[0]!=0)throw std::runtime_error("nonzero empty hand delta");out.write((char*)&base,4);out.write((char*)q.data(),H*2);}char extra;if(in.get(extra))throw std::runtime_error("trailing data");if(!out)throw std::runtime_error("write failed");std::cout<<"{\"rows\":5798,\"quantized_values\":468072540,\"converted\":true}\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
